action.command:
python3 -c "$(cat <<'PY'
import json, re, sys
try:
    data = json.load(sys.stdin)
except Exception:
    raise SystemExit(0)
def commands(o):
    if isinstance(o, dict):
        for k, v in o.items():
            if k == 'command' and isinstance(v, str):
                yield v
            else:
                yield from commands(v)
    elif isinstance(o, list):
        for v in o:
            yield from commands(v)
pattern = re.compile(
    r'\bsam\s+(deploy|delete|sync)\b'
    r'|\baws\s+cloudformation\s+(create-stack|update-stack|deploy|delete-stack)\b'
    r'|\baws\s+s3(api)?\s+(cp|sync|mv|rm|rb|mb|put-object|delete-object)\b'
    r'|\baws\s+bedrock-agent\s+(start-ingestion-job|delete-\S+|create-\S+)'
    r'|\baws\s+cognito-idp\s+admin-\S+'
    r'|\baws\s+logs\s+delete-\S+')
hit = next((c for c in commands(data) if pattern.search(c)), None)
if hit:
    print(json.dumps({'hookSpecificOutput': {
        'permissionDecision': 'ask',
        'permissionDecisionReason': 'This command creates, modifies or deletes AWS resources. Confirm the account, region and resources before continuing.'}}))
PY
)"
